      id: row.id,
      jobId: row.job_id,
      title: row.title,
      status: row.status,
      severity: row.severity,
      assignee: row.assignee,
      dueAt: row.due_at,
      closedAt: row.closed_at,
      approvalId: row.approval_id,
      data: fromJson(row.data_json),
